int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W;
    cin >> H >> W;
    vector<vector<int>> a(H, vector<int>(W));
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) cin >> a[i][j];
    }

    vector<array<int, 4>> ans;

    for (int i = 0; i < H; ++i) {
        if (i % 2 == 0) {
            for (int j = 0; j < W; ++j) {
                if (j + 1 < W) {
                    if (a[i][j] % 2 == 1) {
                        a[i][j]--;
                        a[i][j + 1]++;
                        ans.push_back({i + 1, j + 1, i + 1, j + 2});
                    }
                } else if (i + 1 < H) {
                    if (a[i][j] % 2 == 1) {
                        a[i][j]--;
                        a[i + 1][j]++;
                        ans.push_back({i + 1, j + 1, i + 2, j + 1});
                    }
                }
            }
        } else {
            for (int j = W - 1; j >= 0; --j) {
                if (j - 1 >= 0) {
                    if (a[i][j] % 2 == 1) {
                        a[i][j]--;
                        a[i][j - 1]++;
                        ans.push_back({i + 1, j + 1, i + 1, j});
                    }
                } else if (i + 1 < H) {
                    if (a[i][j] % 2 == 1) {
                        a[i][j]--;
                        a[i + 1][j]++;
                        ans.push_back({i + 1, j + 1, i + 2, j + 1});
                    }
                }
            }
        }
    }

    cout << ans.size() << '\n';
    for (auto &op : ans) {
        cout << op[0] << ' ' << op[1] << ' ' << op[2] << ' ' << op[3] << '\n';
    }

