#include <stdio.h>

int main() {
    int h, w;
    scanf("%d %d", &h, &w);
    int a[h][w];
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            scanf("%d", &a[i][j]);
        }
    }

    // We'll store moves: each move is from (y1,x1) to (y2,x2), 1-indexed
    int moves[2500][4]; // max moves = h*w
    int move_count = 0;

    // Traverse in row-major order
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            if (a[i][j] % 2 == 1) {
                // Determine next cell
                int ni = i, nj = j;
                if (j + 1 < w) {
                    nj = j + 1;
                } else if (i + 1 < h) {
                    ni = i + 1;
                    nj = 0;
                } else {
                    continue; // last cell, nothing to do
                }
                // Move one coin
                a[i][j]--;
                a[ni][nj]++;
                moves[move_count][0] = i + 1;
                moves[move_count][1] = j + 1;
                moves[move_count][2] = ni + 1;
                moves[move_count][3] = nj + 1;
                move_count++;
            }
        }
    }

    printf("%d\n", move_count);
    for (int k = 0; k < move_count; k++) {
        printf("%d %d %d %d\n", moves[k][0], moves[k][1], moves[k][2], moves[k][3]);
    }

    return 0;
}

