import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int H = fs.nextInt();
        int W = fs.nextInt();

        int[][] a = new int[H][W];
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                a[i][j] = fs.nextInt();
            }
        }

        List<int[]> ops = new ArrayList<>();

        for (int i = 0; i < H; i++) {
            if (i % 2 == 0) {
                for (int j = 0; j < W - 1; j++) {
                    if ((a[i][j] & 1) == 1) {
                        a[i][j]--;
                        a[i][j + 1]++;
                        ops.add(new int[]{i + 1, j + 1, i + 1, j + 2});
                    }
                }
                if (i != H - 1 && (a[i][W - 1] & 1) == 1) {
                    a[i][W - 1]--;
                    a[i + 1][W - 1]++;
                    ops.add(new int[]{i + 1, W, i + 2, W});
                }
            } else {
                for (int j = W - 1; j >= 1; j--) {
                    if ((a[i][j] & 1) == 1) {
                        a[i][j]--;
                        a[i][j - 1]++;
                        ops.add(new int[]{i + 1, j + 1, i + 1, j});
                    }
                }
                if (i != H - 1 && (a[i][0] & 1) == 1) {
                    a[i][0]--;
                    a[i + 1][0]++;
                    ops.add(new int[]{i + 1, 1, i + 2, 1});
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        sb.append(ops.size()).append('\n');
        for (int[] op : ops) {
            sb.append(op[0]).append(' ')
              .append(op[1]).append(' ')
              .append(op[2]).append(' ')
              .append(op[3]).append('\n');
        }
        System.out.print(sb.toString());
    }
